#include <cstdio>
#include "GreeterRuntime.h"

// From the 3rdParty::Lua package, resolved out of the O3DE package store -
// demonstrates ThirdPartyDependencies producing real include paths and a real link.
extern "C" {
#include <Lua/lua.h>
#include <Lua/lauxlib.h>
#include <Lua/lualib.h>
}

// From the Vcpkg::zlib port - include dir, import lib, and staged zlib1.dll all come from
// vcpkg's own install database.
#include <zlib.h>

// Generated by this module's CodeGenSteps at build time.
#include "BuildInfo.h"
extern const int kGeneratedAnswer;

int main()
{
    std::printf("%s\n", Greeter_GetGreeting());

    lua_State* lua = luaL_newstate();
    luaL_openlibs(lua);
    if (luaL_dostring(lua, "return 6 * 7") == LUA_OK)
    {
        std::printf("Lua %s says: %lld\n", LUA_VERSION_MAJOR "." LUA_VERSION_MINOR,
            static_cast<long long>(lua_tointeger(lua, -1)));
    }
    lua_close(lua);

    std::printf("zlib (from vcpkg) version: %s\n", zlibVersion());

    std::printf("%s / answer %d\n", GENERATED_BUILD_NAME, kGeneratedAnswer);
    return 0;
}
